      ...validatedData,
      id: validatedData.id || projectData.id, // safeParse might strip id if not in schema properly
      meta: {
        ...validatedData.meta,
        author: userId,
        updated: new Date().toISOString()
      }
    };

    // 3. Persist
    return this.projectRepository.save(dataToSave);
  }
}

